package uimodtest

// Fix-verification snapshots (2026-11 audit, wave F): renders the key fixed
// frames through the REAL desktop assembly into audit/screenshots/fix-verify/
// for visual self-check (read_image). Run explicitly:
//
//	go test ./internal/ui/uimodtest -run TestFixVerifySnapshots -count=1
//
// Covers US-01 (live per-iteration reasoning interleave) and RG-02 (full-mode
// sandbox warning state). The module-level UX-02/UD-01 frames are generated by
// internal/regression's fix-verify snapshot test.

import (
	"image/png"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/egoist/mygo/ui"

	"github.com/zeokeel/zeokeel/internal/contracts"
)

// fixVerifyDir is audit/screenshots/fix-verify relative to this package dir.
const fixVerifyDir = "../../../audit/screenshots/fix-verify"

func saveFixFrame(t *testing.T, tester *ui.Tester, name string) {
	t.Helper()
	if err := os.MkdirAll(fixVerifyDir, 0o755); err != nil {
		t.Fatalf("mkdir fix-verify: %v", err)
	}
	path := filepath.Join(fixVerifyDir, name)
	file, err := os.Create(path)
	if err != nil {
		t.Fatalf("create %s: %v", path, err)
	}
	defer file.Close()
	if err := png.Encode(file, tester.Image()); err != nil {
		t.Fatalf("encode %s: %v", path, err)
	}
	t.Logf("fix-verify frame saved: %s", path)
}

// TestFixVerifySnapshots renders the US-01 and RG-02 fixed frames.
func TestFixVerifySnapshots(t *testing.T) {
	// US-01: a live two-iteration turn in verbose mode shows two per-iteration
	// reasoning blocks interleaved with the tool card (not one aggregated block).
	server := newUS01Server(t)
	settings := us01Settings(server.URL)
	root, uiRoot, _ := bootDesktop(t, t.TempDir(), settings)
	chat := requireChat(t, root)
	id, err := chat.NewSession("US01 fix-verify")
	if err != nil {
		t.Fatalf("NewSession: %v", err)
	}
	tester := ui.NewTester(uiRoot.View, 1200, 800)
	tester.Frame()
	if err := uiRoot.Navigator().Push("session"); err != nil {
		t.Fatalf("Push(session): %v", err)
	}
	if err := chat.Send(id, "render the two-iteration turn"); err != nil {
		t.Fatalf("Send: %v", err)
	}
	waitIdle(t, chat, id, 30*time.Second)
	if !us01FrameUntil(tester, "思考", 5*time.Second) {
		t.Fatalf("no reasoning trigger; texts=%v", tester.Texts())
	}
	// Open the first reasoning block so the frame shows the per-iteration text.
	if err := tester.Click("思考"); err != nil {
		t.Fatalf("open reasoning: %v", err)
	}
	tester.Advance(300 * time.Millisecond)
	tester.Frame()
	saveFixFrame(t, tester, "us01-live-interleave.png")

	// RG-02: full mode renders the mode-aware sandbox WARNING, not the success
	// badge. Boot a fresh assembly with agent.permission=full.
	fullSettings := &memSettings{values: map[string]string{
		contracts.SettingsChatModel:      "test-model",
		contracts.SettingsChatBaseURL:    server.URL,
		contracts.SettingAgentPermission: contracts.PermissionFull,
	}}
	root2, uiRoot2, _ := bootDesktop(t, t.TempDir(), fullSettings)
	_ = root2
	tester2 := ui.NewTester(uiRoot2.View, 1200, 800)
	tester2.Frame()
	if err := tester2.Click("设置"); err != nil {
		t.Fatalf("open settings: %v; texts=%v", err, tester2.Texts())
	}
	tester2.Frame()
	if err := tester2.Click("行为与限额"); err != nil {
		t.Fatalf("open behavior page: %v; texts=%v", err, tester2.Texts())
	}
	tester2.Frame()
	if !strings.Contains(strings.Join(tester2.Texts(), "\n"), "完全访问") {
		t.Fatalf("RG-02 full-mode warning missing; texts=%v", tester2.Texts())
	}
	saveFixFrame(t, tester2, "rg02-full-mode-warning.png")
}
